/** Key figures, written so each `clue` is a fair quiz prompt on its own. */
export interface Person {
  id: string;
  name: string;
  /** The identification a quiz would accept: "Who was ___?" */
  role: string;
  /** A distinctive detail that identifies them and nothing else. */
  clue: string;
  /** Primary book id where they appear. */
  book: string;
  era: string;
  alsoKnownAs?: string[];
  facts?: string[];
  /** Family, so relationship questions can be generated rather than authored. */
  father?: string;
  mother?: string;
  spouse?: string;
  children?: string[];
  /** Tribe of Israel, where it is known and testable. */
  tribe?: string;
  /** How they died, when that is the memorable part. */
  died?: string;
  /** Which of the standing groups they belong to: apostle, judge, patriarch… */
  group?: string;
}

